#pragma once

#include <map>
#include <string>

// A record is an ordered field map. "a=1;b=2" parses to {a:1, b:2}; an empty
// segment is skipped and a segment with no '=' names a field with no value.
using Record = std::map<std::string, std::string>;

inline Record parse_record(const std::string& text) {
    Record out;
    std::string::size_type start = 0;
    while (start <= text.size()) {
        const std::string::size_type stop = text.find(';', start);
        const std::string segment =
            text.substr(start, stop == std::string::npos ? std::string::npos : stop - start);
        if (!segment.empty()) {
            const std::string::size_type split = segment.find('=');
            if (split == std::string::npos) {
                out[segment] = "";
            } else {
                out[segment.substr(0, split)] = segment.substr(split + 1);
            }
        }
        if (stop == std::string::npos) break;
        start = stop + 1;
    }
    return out;
}

