#pragma once

#include <string>

#include "record.hpp"

// Fields in key order, joined by ';'. A field with no value renders as "k=".
inline std::string render(const Record& record) {
    std::string out;
    for (const auto& field : record) {
        if (!out.empty()) out += ';';
        out += field.first;
        out += '=';
        out += field.second;
    }
    return out;
}

