    std::string::size_type start = 0;
    while (start <= text.size()) {
        const std::string::size_type stop = text.find(',', start);
        std::string term =
            text.substr(start, stop == std::string::npos ? std::string::npos : stop - start);
        if (!term.empty()) {
            if (term[0] == '-') {
                mask.drop.push_back(term.substr(1));
            } else {
                mask.keep.push_back(term);
            }
        }
        if (stop == std::string::npos) break;
        start = stop + 1;
    }
    return mask;
}

