#pragma once

#include <string>
#include <vector>

// Split on a single character, keeping empty pieces. "a,,b" -> {"a", "", "b"}.
inline std::vector<std::string> split(const std::string& text, char separator) {
    std::vector<std::string> out;
    std::string::size_type start = 0;
    while (true) {
        const std::string::size_type stop = text.find(separator, start);
        if (stop == std::string::npos) {
            out.push_back(text.substr(start));
            return out;
        }
        out.push_back(text.substr(start, stop - start));
        start = stop + 1;
    }
}

inline std::string join(const std::vector<std::string>& pieces, const std::string& glue) {
    std::string out;
    for (std::vector<std::string>::size_type i = 0; i < pieces.size(); ++i) {
        if (i != 0) out += glue;
        out += pieces[i];
    }
    return out;
}

// Every run of spaces and tabs collapsed to one space; ends left alone.
inline std::string collapse_spaces(const std::string& text) {
    std::string out;
    bool in_run = false;
    for (const char c : text) {
        const bool blank = c == ' ' || c == '\t';
        if (blank) {
            if (!in_run) out += ' ';
            in_run = true;
        } else {
            out += c;
            in_run = false;
        }
    }
    return out;
}

