#pragma once

#include <string>
#include <vector>

#include "text.hpp"

// Consecutive blank lines reduced to one. A line of only spaces counts blank.
inline std::string squeeze_blank_lines(const std::string& text) {
    const std::vector<std::string> lines = split(text, '\n');
    std::vector<std::string> out;
    bool previous_blank = false;
    for (const std::string& line : lines) {
        bool blank = true;
        for (const char c : line) {
            if (c != ' ' && c != '\t') { blank = false; break; }
        }
        if (blank && previous_blank) continue;
        out.push_back(line);
        previous_blank = blank;
    }
    return join(out, "\n");
}

