import type { Point } from "./geometry.ts";

export type Board = { readonly width: number; readonly height: number };

export function inBounds(board: Board, point: Point): boolean {
  return point.x >= 0 && point.y >= 0 && point.x < board.width && point.y < board.height;
}

// The first free cell in row-major order, or null when the board is full.
export function firstFreeCell(board: Board, taken: readonly Point[]): Point | null {
  for (let y = 0; y < board.height; y += 1) {
    for (let x = 0; x < board.width; x += 1) {
      if (!taken.some((cell) => cell.x === x && cell.y === y)) return { x, y };
    }
  }
  return null;
}

