import { inBounds, firstFreeCell } from "./board.ts";
import type { Board } from "./board.ts";
import { add, equals } from "./geometry.ts";
import type { Point } from "./geometry.ts";
import { delta } from "./direction.ts";
import type { Direction } from "./direction.ts";

export type GameState = {
  board: Board;
  snake: Point[];
  food: Point | null;
  alive: boolean;
  score: number;
};

export function create(width: number, height: number): GameState {
  return {
    board: { width, height },
    snake: [{ x: 1, y: 0 }],
    food: { x: 3, y: 0 },
    alive: true,
    score: 0,
  };
}

// One tick. The head advances; eating grows the snake and re-seeds the food at
// the first free cell in row-major order; a wall or the snake's own body ends
// the game and leaves the snake where it was.
export function step(state: GameState, direction: Direction): GameState {
  if (!state.alive) return state;
  const head = add(state.snake[0], delta(direction));
  if (!inBounds(state.board, head)) return { ...state, alive: false };
  const eats = state.food !== null && equals(head, state.food);
  const body = eats ? state.snake : state.snake.slice(0, state.snake.length - 1);
  if (body.some((cell) => equals(cell, head))) return { ...state, alive: false };
  const snake = [head, ...body];
  return {
    ...state,
    snake,
    food: eats ? firstFreeCell(state.board, snake) : state.food,
    score: state.score + (eats ? 1 : 0),
  };
}

