"""The playfield: a rectangle of 0 (empty) and 1 (filled) cells."""


def blank(width, height):
    return [[0] * width for _ in range(height)]


def width_of(grid):
    return len(grid[0]) if grid else 0


def height_of(grid):
    return len(grid)


def occupied(grid, x, y):
    return grid[y][x] == 1


def render(grid):
    """One text row per grid row, '.' for empty and '#' for filled."""
    return "\n".join("".join("#" if cell else "." for cell in row) for row in grid)


def full_rows(grid):
    """The indices of every completely filled row, top to bottom."""
    return [y for y, row in enumerate(grid) if all(row)]


def clear_rows(grid, rows):
    """Drop the named rows and push empty rows in at the top."""
    kept = [list(row) for y, row in enumerate(grid) if y not in set(rows)]
    empty = [[0] * width_of(grid) for _ in range(len(grid) - len(kept))]
    return empty + kept

