export type Schema = {
  required: readonly string[];
  properties: Record<string, { type: string }>;
  additionalProperties: boolean;
};

// A deliberately small validator: enough to enforce the committed schema, and
// no more. Every refusal names the offending key.
export function validate(schema: Schema, value: unknown): string[] {
  const problems: string[] = [];
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return ["the config must be an object"];
  }
  const record = value as Record<string, unknown>;
  for (const key of schema.required) {
    if (!(key in record)) problems.push(`missing required key ${key}`);
  }
  for (const key of Object.keys(record)) {
    const declared = schema.properties[key];
    if (declared === undefined) {
      if (!schema.additionalProperties) problems.push(`unknown key ${key}`);
      continue;
    }
    const actual = typeof record[key] === "number"
      ? Number.isInteger(record[key]) ? "integer" : "number"
      : typeof record[key];
    if (actual !== declared.type) problems.push(`key ${key} must be ${declared.type}`);
  }
  return problems;
}

