import { readFileSync } from "node:fs";
import { validate } from "./schema.ts";
import type { Schema } from "./schema.ts";
import { withDefaults } from "./defaults.ts";

export function loadSchema(path = "schema/config.schema.json"): Schema {
  return JSON.parse(readFileSync(path, "utf8")) as Schema;
}

export function parseConfig(text: string): {
  config: Record<string, unknown> | null;
  problems: string[];
} {
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch (error) {
    return { config: null, problems: [`the config is not JSON: ${String(error)}`] };
  }
  const problems = validate(loadSchema(), raw);
  if (problems.length > 0) return { config: null, problems };
  return { config: withDefaults(raw as Record<string, unknown>), problems: [] };
}

