  const { problems } = parseConfig(
    JSON.stringify({ host: "a", port: 1, retries: "many" }),
  );
  assert.equal(problems.length, 1);
  assert.match(problems[0], /retries/);
});

test("the committed schema itself declares the key", () => {
  const schema = JSON.parse(readFileSync("schema/config.schema.json", "utf8"));
  assert.equal(schema.properties.retries?.type, "integer");
  assert.ok(!schema.required.includes("retries"), "retries is optional");
});

