#pragma once

#include <algorithm>
#include <vector>

#include "sample.hpp"

inline double total_ms(const Samples& samples) {
    double total = 0.0;
    for (const Sample& sample : samples) total += sample.ms;
    return total;
}

inline double max_ms(const Samples& samples) {
    double largest = 0.0;
    for (const Sample& sample : samples) largest = std::max(largest, sample.ms);
    return largest;
}

inline double mean_ms(const Samples& samples) {
    return samples.empty() ? 0.0 : total_ms(samples) / static_cast<double>(samples.size());
}

